-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'BANCO DE DADOS' and a.numero = 16
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 16 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 16', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 16 (10 questões discursivas)',
      '/MATERIAIS/TECNICO-INFORMATICA-INTERNET/BANCO-DE-DADOS/ATIVIDADES/ATIVIDADE-PRATICA-AULA-16.html', 10, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Explique por que é preciso juntar as tabelas turma e curso para atender o pedido.', 0.2, 'A turma guarda **só o id_curso** (chave estrangeira); o **nome do curso** está na tabela **curso**. Por causa da **normalização**, é preciso **juntar** as duas tabelas.', 'Nota cheia (0,2): cita que o nome está em outra tabela/ligada pela FK. Metade (0,1): só diz "para ligar" sem dizer onde está o nome. Zero (0): sem relação.'),
      (v_atividade, 1, 2, 'Escreva a consulta com INNER JOIN e apelidos de tabela, mostrando o nome do curso com o apelido curso.', 0.4, 'SELECT t.codigo, t.turno, c.nome AS curso FROM turma t INNER JOIN curso c ON c.id_curso = t.id_curso;', 'Nota cheia (0,4): JOIN com ON correto (FK = PK), apelidos e AS curso. Metade (0,2): JOIN certo, mas sem apelido ou sem uma coluna. Zero (0): sem ON ou ligação errada.'),
      (v_atividade, 1, 3, 'Explique o papel do ON e o que aconteceria se ele fosse ligado a colunas erradas.', 0.4, 'O **ON** diz **quais colunas ligam** as tabelas (t.id_curso = c.id_curso). Sem ligação ou com colunas erradas, sai o **produto cartesiano** (cada turma combinada com todos os cursos) ou um resultado **errado**.', 'Nota cheia (0,4): papel do ON + produto cartesiano/resultado errado. Metade (0,2): só um. Zero (0): diz que o ON ordena ou filtra grupos.'),
      (v_atividade, 2, 1, 'Diga quais tabelas entram na consulta e qual delas faz a ponte entre aluno e turma.', 0.2, 'Entram **matricula, aluno, turma e curso**; a **matricula** (tabela **associativa**) faz a ponte entre aluno e turma.', 'Nota cheia (0,2): as quatro tabelas + matricula como ponte. Metade (0,1): só um dos dois. Zero (0): sem relação.'),
      (v_atividade, 2, 2, 'Escreva a consulta completa.', 0.4, 'SELECT a.nome AS aluno, t.codigo AS turma, c.nome AS curso FROM matricula m JOIN aluno a ON a.id_aluno = m.id_aluno JOIN turma t ON t.id_turma = m.id_turma JOIN curso c ON c.id_curso = t.id_curso WHERE m.situacao = ''ativa'' ORDER BY c.nome, a.nome;', 'Nota cheia (0,4): três JOIN com os ON certos, filtro ''ativa'' e ORDER BY. Metade (0,2): falta o filtro ou a ordenação, ou um ON errado. Zero (0): sem JOIN.'),
      (v_atividade, 2, 3, 'Explique por que cada JOIN precisa do seu próprio ON.', 0.4, 'Cada JOIN **acrescenta uma tabela** e precisa dizer **como ela se liga** às anteriores (a sua **FK = PK**); sem isso, aquela tabela gera **produto cartesiano**.', 'Nota cheia (0,4): cada tabela tem sua ligação + risco de produto cartesiano. Metade (0,2): só um. Zero (0): sem relação.'),
      (v_atividade, 3, 1, 'Explique a diferença entre INNER JOIN e LEFT JOIN.', 0.2, 'O **INNER JOIN** traz **só as linhas com par** nas duas tabelas; o **LEFT JOIN** traz **todas as linhas da tabela da esquerda**, com ou sem par (sem par, as colunas da direita vêm **NULL**).', 'Nota cheia (0,2): as duas definições. Metade (0,1): só uma. Zero (0): definições trocadas.'),
      (v_atividade, 3, 2, 'Escreva a consulta de todos os cursos com o código das suas turmas.', 0.4, 'SELECT c.nome, t.codigo FROM curso c LEFT JOIN turma t ON t.id_curso = c.id_curso;', 'Nota cheia (0,4): curso à esquerda com LEFT JOIN e ON correto (ou turma RIGHT JOIN curso). Metade (0,2): LEFT JOIN com as tabelas invertidas. Zero (0): INNER JOIN.'),
      (v_atividade, 3, 3, 'Altere a consulta para mostrar só os cursos sem nenhuma turma e explique o filtro.', 0.4, 'SELECT c.nome FROM curso c LEFT JOIN turma t ON t.id_curso = c.id_curso WHERE t.id_turma IS NULL; — curso sem turma fica com as colunas de turma **NULL**, por isso o filtro é **IS NULL** (nunca = NULL).', 'Nota cheia (0,4): filtro IS NULL na coluna da direita + explicação. Metade (0,2): só a consulta ou só a explicação. Zero (0): usa = NULL ou filtra a coluna de curso.'),
      (v_atividade, 4, 1, 'Escreva as consultas da quantidade de alunos e da quantidade de alunos com e-mail.', 0.2, 'SELECT count(*) FROM aluno; e SELECT count(email) FROM aluno;', 'Nota cheia (0,2): as duas. Metade (0,1): uma. Zero (0): nenhuma.'),
      (v_atividade, 4, 2, 'Escreva as consultas da média do valor mensal e da matrícula mais recente.', 0.4, 'SELECT avg(valor_mensal) FROM curso; e SELECT max(data_matricula) FROM matricula;', 'Nota cheia (0,4): avg e max corretos. Metade (0,2): uma das duas. Zero (0): funções trocadas.'),
      (v_atividade, 4, 3, 'Explique por que count(*) e count(email) podem dar resultados diferentes.', 0.4, '**count(*)** conta **todas as linhas**; **count(email)** conta só os valores **não nulos**: as funções de agregação **ignoram os NULL**, então alunos sem e-mail ficam de fora.', 'Nota cheia (0,4): explica os dois + NULL. Metade (0,2): só um. Zero (0): diz que são iguais.'),
      (v_atividade, 5, 1, 'Explique para que serve o GROUP BY.', 0.2, 'O **GROUP BY** junta as linhas com o **mesmo valor** e calcula a agregação **por grupo**.', 'Nota cheia (0,2): definição. Zero (0): confunde com ordenação.'),
      (v_atividade, 5, 2, 'Escreva a consulta pedida.', 0.4, 'SELECT c.nome AS curso, count(m.id_matricula) AS matriculas FROM curso c JOIN turma t ON t.id_curso = c.id_curso JOIN matricula m ON m.id_turma = t.id_turma GROUP BY c.nome ORDER BY matriculas DESC;', 'Nota cheia (0,4): JOIN até matricula, count, GROUP BY c.nome e ORDER BY DESC. Metade (0,2): falta a ordenação ou um JOIN. Zero (0): sem GROUP BY.'),
      (v_atividade, 5, 3, 'Explique a regra das colunas no GROUP BY e o erro que aparece quando ela não é cumprida.', 0.4, 'Toda coluna do SELECT **sem função de agregação** precisa estar **no GROUP BY**; senão o PostgreSQL dá o erro **must appear in the GROUP BY clause** ("deve aparecer na cláusula GROUP BY").', 'Nota cheia (0,4): regra + erro. Metade (0,2): só um. Zero (0): sem relação.'),
      (v_atividade, 6, 1, 'Explique o erro do colega.', 0.2, 'O **WHERE não aceita função de agregação**: filtra **linhas antes** de agrupar; para filtrar pela contagem, usa-se **HAVING**.', 'Nota cheia (0,2): WHERE sem agregação + usar HAVING. Metade (0,1): só um. Zero (0): sem relação.'),
      (v_atividade, 6, 2, 'Escreva a consulta correta.', 0.4, 'SELECT t.codigo, count(*) AS alunos FROM matricula m JOIN turma t ON t.id_turma = m.id_turma WHERE m.situacao = ''ativa'' GROUP BY t.codigo HAVING count(*) < 5;', 'Nota cheia (0,4): WHERE para ''ativa'', GROUP BY e HAVING count < 5. Metade (0,2): falta o filtro ''ativa'' ou o GROUP BY. Zero (0): mantém a agregação no WHERE.'),
      (v_atividade, 6, 3, 'Explique a ordem de execução das cláusulas e onde entram o WHERE e o HAVING.', 0.4, 'Ordem: **FROM/JOIN → WHERE → GROUP BY → HAVING → SELECT → ORDER BY → LIMIT**. O **WHERE** age **antes** do agrupamento (linhas) e o **HAVING depois** (grupos).', 'Nota cheia (0,4): ordem com WHERE antes e HAVING depois do GROUP BY. Metade (0,2): só a posição de WHERE e HAVING. Zero (0): ordem invertida.'),
      (v_atividade, 7, 1, 'Diga quais tabelas são juntadas e qual função soma as parcelas.', 0.2, 'Juntam-se **curso, turma, matricula e parcela**; a soma é feita com **SUM(p.valor)**.', 'Nota cheia (0,2): tabelas + SUM. Metade (0,1): só um. Zero (0): sem relação.'),
      (v_atividade, 7, 2, 'Escreva a consulta do faturamento previsto por curso, do maior para o menor.', 0.4, 'SELECT c.nome, sum(p.valor) AS faturamento FROM curso c JOIN turma t ON t.id_curso = c.id_curso JOIN matricula m ON m.id_turma = t.id_turma JOIN parcela p ON p.id_matricula = m.id_matricula GROUP BY c.nome ORDER BY faturamento DESC;', 'Nota cheia (0,4): JOIN até parcela, SUM, GROUP BY e ORDER BY DESC. Metade (0,2): falta a ordenação ou um JOIN. Zero (0): sem SUM ou sem GROUP BY.'),
      (v_atividade, 7, 3, 'Mostre como deixar só o curso de maior faturamento e justifique.', 0.4, 'Acrescentar **LIMIT 1** depois do **ORDER BY faturamento DESC**: a ordem decrescente põe o maior em primeiro e o LIMIT traz só essa linha.', 'Nota cheia (0,4): ORDER BY DESC + LIMIT 1 com justificativa (ou subconsulta equivalente). Metade (0,2): sem justificativa. Zero (0): usa max(c.nome) ou WHERE sum().'),
      (v_atividade, 8, 1, 'Explique o que é uma subconsulta.', 0.2, 'É uma **consulta dentro de outra**, escrita **entre parênteses**, cujo resultado é usado pela consulta de fora.', 'Nota cheia (0,2): definição. Zero (0): sem relação.'),
      (v_atividade, 8, 2, 'Escreva a consulta dos cursos mais caros que a média.', 0.4, 'SELECT nome, valor_mensal FROM curso WHERE valor_mensal > (SELECT avg(valor_mensal) FROM curso);', 'Nota cheia (0,4): subconsulta com avg e operador >. Metade (0,2): usa >= ou falta coluna. Zero (0): avg direto no WHERE sem subconsulta.'),
      (v_atividade, 8, 3, 'Escreva a consulta dos alunos com parcela vencida e não paga e explique por que se usa IN e não =.', 0.4, 'SELECT nome FROM aluno WHERE id_aluno IN (SELECT m.id_aluno FROM matricula m JOIN parcela p ON p.id_matricula = m.id_matricula WHERE p.data_pagamento IS NULL AND p.vencimento < current_date); — usa-se **IN** porque a subconsulta devolve **vários valores**; com **=** dá erro quando volta **mais de uma linha**.', 'Nota cheia (0,4): consulta correta + explicação do IN. Metade (0,2): só um dos dois. Zero (0): nenhum.'),
      (v_atividade, 9, 1, 'Explique o que o EXISTS verifica.', 0.2, 'O **EXISTS** verifica se a subconsulta devolve **pelo menos uma linha** (verdadeiro ou falso).', 'Nota cheia (0,2): definição. Zero (0): diz que verifica se a tabela existe.'),
      (v_atividade, 9, 2, 'Escreva a consulta dos cursos sem turma usando NOT EXISTS.', 0.4, 'SELECT c.nome FROM curso c WHERE NOT EXISTS (SELECT 1 FROM turma t WHERE t.id_curso = c.id_curso);', 'Nota cheia (0,4): NOT EXISTS ligado ao curso de fora. Metade (0,2): subconsulta sem a ligação com c.id_curso. Zero (0): sem NOT EXISTS.'),
      (v_atividade, 9, 3, 'Escreva a consulta da média de matrículas por turma com uma subconsulta no FROM e explique o apelido.', 0.4, 'SELECT avg(qtd) FROM (SELECT count(*) AS qtd FROM matricula GROUP BY id_turma) AS por_turma; — a subconsulta no FROM vira uma **tabela temporária** e **precisa de apelido** (AS por_turma).', 'Nota cheia (0,4): consulta correta + apelido obrigatório. Metade (0,2): só um dos dois. Zero (0): nenhum.'),
      (v_atividade, 10, 1, 'Explique o problema do relatório 1 e corrija.', 0.2, 'Com **INNER JOIN**, os cursos **sem turma somem**. Correção: **curso c LEFT JOIN turma t** ON t.id_curso = c.id_curso, mantendo **count(t.id_turma)** (que dá 0 para quem não tem turma).', 'Nota cheia (0,2): problema + LEFT JOIN. Metade (0,1): só um. Zero (0): nenhum.'),
      (v_atividade, 10, 2, 'Explique o erro do relatório 2 e corrija.', 0.4, 'A coluna **t.turno** está no SELECT **sem agregação** e **fora do GROUP BY** → erro *must appear in the GROUP BY clause*. Correção: **GROUP BY c.nome, t.turno** (ou tirar t.turno do SELECT).', 'Nota cheia (0,4): erro + correção. Metade (0,2): só um. Zero (0): nenhum.'),
      (v_atividade, 10, 3, 'Explique o que o relatório 3 produz e escreva a versão correta, ligando aluno e turma.', 0.4, 'Sem ligação, sai o **produto cartesiano** (cada aluno com todas as turmas). Correção: SELECT a.nome, t.codigo FROM aluno a JOIN matricula m ON m.id_aluno = a.id_aluno JOIN turma t ON t.id_turma = m.id_turma;', 'Nota cheia (0,4): produto cartesiano + consulta pela matricula. Metade (0,2): só um. Zero (0): nenhum.');
end $$;
